() => {
  const [refType, setRefType] = useState('branch')
  return (
    <>
      <FlagState />
      <UnderlinePanels
        aria-label="Ref type"
        value={refType}
        onChange={({ value }) => {
          action('onChange')({
            value,
          })
          setRefType(value)
        }}
      >
        <UnderlinePanels.Tab value="branch" icon={GitBranchIcon}>
          Branches
        </UnderlinePanels.Tab>
        <UnderlinePanels.Tab value="tag" icon={TagIcon}>
          Tags
        </UnderlinePanels.Tab>
        <UnderlinePanels.Panel value="branch">
          Find or create a branch…
        </UnderlinePanels.Panel>
        <UnderlinePanels.Panel value="tag">
          Search or create a new tag…
        </UnderlinePanels.Panel>
      </UnderlinePanels>
      <p>
        Selected ref type: <strong>{refType}</strong>
      </p>
    </>
  )
}

