() => {
  const [open, setOpen] = useState(false)
  const [refType, setRefType] = useState('branch')
  return (
    <>
      <FlagState />
      <AnchoredOverlay
        open={open}
        onOpen={() => setOpen(true)}
        onClose={() => setOpen(false)}
        renderAnchor={(props) => <Button {...props}>Select ref type</Button>}
        overlayProps={{
          role: 'dialog',
          'aria-modal': true,
          'aria-label': 'Select a ref type',
          style: {
            width: '320px',
          },
        }}
        focusZoneSettings={{
          disabled: true,
        }}
      >
        <UnderlinePanels
          aria-label="Ref type"
          value={refType}
          onChange={({ value }) => {
            action('onChange')({
              value,
            })
            setRefType(value)
          }}
        >
          <UnderlinePanels.Tab value="branch">Branches</UnderlinePanels.Tab>
          <UnderlinePanels.Tab value="tag">Tags</UnderlinePanels.Tab>
          <UnderlinePanels.Panel value="branch">
            Find or create a branch…
          </UnderlinePanels.Panel>
          <UnderlinePanels.Panel value="tag">
            Search or create a new tag…
          </UnderlinePanels.Panel>
        </UnderlinePanels>
      </AnchoredOverlay>
